-- Généré par scripts/demo-seed.mjs : photos des articles de DÉMONSTRATION au format 4:5 (320 × 400), règle du 20/10/2026.
-- Ne touche que les boutiques marquées demo = true (fictives).
update fiila.products p set photo = decode('', 'base64'), photo_type = 'image/png'
  from fiila.shops s where s.id = p.shop_id and s.demo and s.name = 'Awa Couture (démo)' and p.name = 'Robe wax évasée';
